<script setup lang="ts">
import{computed,ref,watch}from'vue';import{useBioStore}from'../stores/bio';
const bio=useBioStore(),enabled=ref(false),focus=ref(25),pause=ref(5),water=ref(45),notifications=ref(false),permissionError=ref('');
watch(()=>[bio.state?.ownerId,bio.state?.revision],()=>{const state=bio.state;if(state){enabled.value=state.enabled;focus.value=state.focusMinutes;pause.value=state.breakMinutes;water.value=state.waterMinutes;notifications.value=state.notifications;}},{immediate:true});
const clock=computed(()=>`${String(Math.floor(bio.remaining/60)).padStart(2,'0')}:${String(bio.remaining%60).padStart(2,'0')}`);
const phaseNames={IDLE:'En reposo',FOCUS:'Intervalo de foco',BREAK:'Pausa',PAUSED_FOCUS:'Foco pausado',PAUSED_BREAK:'Pausa detenida'};
async function permit(){permissionError.value='';if(typeof Notification==='undefined'){permissionError.value='Este navegador no ofrece notificaciones del sistema.';return;}const permission=await Notification.requestPermission();notifications.value=permission==='granted';if(permission!=='granted')permissionError.value='Los avisos dentro de la aplicación seguirán disponibles.';}
const actionLabels:Record<string,string>={start:'Inicio de foco',pause:'Temporizador pausado',resume:'Temporizador reanudado',break:'Inicio de pausa',finish:'Pausa terminada',drink:'Agua confirmada por el usuario',stop:'Recordatorios detenidos'};
</script>
<template><section class="panel workbench" aria-label="Bio-Armadura"><div class="panel-toolbar"><span class="panel-title">BIO-ARMADURA / OPCIONAL</span><span class="session-badge">TÚ DECIDES</span></div><div class="workbench-content"><span class="eyebrow">ESPACIO PARA TOMAR AIRE</span><h2>Tu ritmo de trabajo</h2><p class="muted">Temporizadores y recordatorios que tú configuras. No se observa tu cámara, teclado ni actividad física, ni se infiere tu estado de salud. Los avisos requieren mantener la aplicación abierta.</p><p v-if="bio.error" role="alert" class="library-error">{{ bio.error }}</p><button class="connection-action" :disabled="bio.busy" @click="bio.refresh">Actualizar Bio-Armadura</button>
 <form v-if="bio.state" class="bio-form" @submit.prevent="bio.configure({enabled,focusMinutes:focus,breakMinutes:pause,waterMinutes:water,notifications})"><label class="bio-check"><input v-model="enabled" type="checkbox" :disabled="bio.busy"/>Activar Bio-Armadura</label><div class="bio-fields"><label>Foco (minutos)<input v-model.number="focus" type="number" min="1" max="240" required :disabled="bio.busy"/></label><label>Pausa (minutos)<input v-model.number="pause" type="number" min="1" max="60" required :disabled="bio.busy"/></label><label>Recordatorio de agua (minutos)<input v-model.number="water" type="number" min="5" max="240" required :disabled="bio.busy"/></label></div><label class="bio-check"><input v-model="notifications" type="checkbox" :disabled="bio.busy"/>Usar notificaciones del sistema si tienen permiso</label><button type="button" class="connection-action" @click="permit">Permitir notificaciones del navegador</button><p v-if="permissionError" role="status" class="result-note">{{ permissionError }}</p><p class="result-note">Los cambios de foco y pausa se aplican al próximo intervalo. Desactivar detiene todos los recordatorios. El horario guardado se recupera al recargar; la aplicación cerrada no emite avisos.</p><button class="primary-button" :disabled="bio.busy">Guardar preferencias Bio</button></form>
 <section v-if="bio.state?.enabled" class="bio-timer" aria-label="Temporizador Bio"><p class="eyebrow">{{ phaseNames[bio.state.phase] }}</p><output>{{ clock }}</output><p v-if="bio.phaseDue" role="status">{{ bio.notice }}</p><div class="source-actions"><button v-if="bio.state.phase==='IDLE'" class="primary-button" :disabled="bio.busy" @click="bio.act('start')">Iniciar foco</button><button v-if="['FOCUS','BREAK'].includes(bio.state.phase)" class="connection-action" :disabled="bio.busy" @click="bio.act('pause')">Pausar temporizador</button><button v-if="['PAUSED_FOCUS','PAUSED_BREAK'].includes(bio.state.phase)" class="connection-action" :disabled="bio.busy" @click="bio.act('resume')">Reanudar temporizador</button><button v-if="['FOCUS','PAUSED_FOCUS'].includes(bio.state.phase)" class="connection-action" :disabled="bio.busy" @click="bio.act('break')">Tomar pausa</button><button v-if="['BREAK','PAUSED_BREAK'].includes(bio.state.phase)" class="connection-action" :disabled="bio.busy" @click="bio.act('finish')">Terminar pausa</button><button class="connection-action" :disabled="bio.busy" @click="bio.act('drink')">Tomé agua</button><button class="connection-action" :disabled="bio.busy" @click="bio.act('stop')">Detener recordatorios</button><button class="connection-action" @click="bio.muted=!bio.muted">{{ bio.muted?'Volver a mostrar avisos':'Silenciar en esta pestaña' }}</button></div><p v-if="bio.waterDue" role="status" class="result-note">Recordatorio de agua pendiente.</p><p v-else-if="bio.state.waterAt" class="result-note">Próximo recordatorio de agua: {{ new Date(bio.state.waterAt).toLocaleTimeString('es-PE') }}.</p></section>
 <details v-if="bio.state?.events.length"><summary>Últimas acciones confirmadas</summary><ul><li v-for="(event,index) in bio.state.events" :key="index">{{ actionLabels[event.action]??event.action }} · {{ new Date(event.createdAt).toLocaleString('es-PE') }}</li></ul></details>
 </div></section></template>
<style scoped>.bio-form{display:grid;gap:15px;margin:24px 0}.bio-check{display:flex;gap:10px;align-items:center}.bio-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px}.bio-fields label{display:grid;gap:8px;font-size:12px}.bio-fields input{width:100%;padding:12px;background:#08151a;color:#dcebf0;border:1px solid #29434b;border-radius:6px}.bio-form button{justify-self:start}.bio-timer{padding:24px 0;border-top:1px solid #233a41}.bio-timer output{display:block;font-size:52px;font-variant-numeric:tabular-nums;margin:18px 0;color:#92f8c2}details{font-size:12px;margin-top:24px}li{margin:10px 0;color:#8ba8b4}</style>
